interface.definition:
a!localVariables(
  local!isOldVersion:if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    false,
    if(
      todatetime(ri!nomination.createdOn)<#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11589045",
      true,
      false)
  ),
  local!applicablePathwaysPerHR: #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050345"(
    refTypeId : 32,
    returnCDT: true(),
    isActive: true()
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
  label: "HR Review",
  labelColor: "SECONDARY",
  contents: {
    #"SYSTEM_SYSRULES_richTextDisplayField"(
      labelPosition: "COLLAPSED",
      value: {
        #"SYSTEM_SYSRULES_richTextItem_v1"(
          text: { "To be completed by HR Personnel" },
          size: "SMALL",
          style: "EMPHASIS"
        )
      }
    ),
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_radioButtonField"(
                  /*Changes according to APAP-19643- Updation of verbiage*/
                  /*label: "Does the individual have an AQR 1 or 2?",*/
                  label: "Does the individual have an AQR 1, 2 or 3?",
                  labelPosition: "ABOVE",
                  required: true,
                  instructions: "Note - If no, additional vetting is required",
                  choiceLabels: { "Yes", "No", #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185" },
                  choiceValues: { "Yes", "No", #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185" },
                  value: index(
                    ri!nomination,
                    "isAQR1or2",
                    toboolean({})
                  ),
                  saveInto: { ri!nomination.isAQR1or2 },
                  choiceLayout: "COMPACT"
                ),
                #"SYSTEM_SYSRULES_radioButtonField"(
                  label: "Is the candidate in good standing within the past 3 fiscal years?",
                  labelPosition: "ABOVE",
                  helpTooltip: "Good Standing Includes US-FM HR People Support check of PIP Database, IEM (Investigations), YELP (year-end low performer) flag, and Functional LP database",
                  instructions: "Note - If no, additional vetting is required",
                  choiceLabels: { "Yes", "No" },
                  choiceValues: { true, false },
                  value: index(
                    ri!nomination,
                    "isCandidateGoodStanding",
                    toboolean({})
                  ),
                  saveInto: { ri!nomination.isCandidateGoodStanding },
                  required: true,
                  choiceLayout: "COMPACT",
                  validations: {}
                ),
                #"SYSTEM_SYSRULES_radioButtonField"(
                  label: "Is additional vetting required?",
                  labelPosition: "ABOVE",
                  choiceLabels: { "Yes", "No" },
                  choiceValues: { true, false },
                  value: index(
                    ri!nomination,
                    "isVettingRequired",
                    toboolean({})
                  ),
                  saveInto: { ri!nomination.isVettingRequired },
                  required: true,
                  choiceLayout: "COMPACT",
                  validations: {}
                )
              }
            ),
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_integerField"(
                        label: "Years of Service",
                        labelPosition: "ABOVE",
                        value: index(ri!nomination, "yearsofServiceHR", null),
                        saveInto: { ri!nomination.yearsofServiceHR },
                        refreshAfter: "UNFOCUS"
                      )
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_textField"(
                        label: "Years of Service per nomination",
                        labelPosition: "ABOVE",
                        value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                          value: index(ri!nomination, "yearsWithFirm", {}),
                          isBoolean: false
                        ),
                        readOnly: true
                      )
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_textField"(
                        label: "Expected MD Promotion Date per latest available pipeline",
                        labelPosition: "ABOVE",
                        value: index(ri!nomination, "mdPromotionDateHR", null),
                        saveInto: { ri!nomination.mdPromotionDateHR },
                        required: or(
                          index(
                            ri!nomination,
                            "subPositionTypeId",
                            tointeger(null)
                          ) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454622",
                          index(
                            ri!nomination,
                            "subPositionTypeId",
                            tointeger(null)
                          ) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454629"
                        ),
                        disabled: or(
                          index(
                            ri!nomination,
                            "subPositionTypeId",
                            tointeger(null)
                          ) = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
                          index(
                            ri!nomination,
                            "subPositionTypeId",
                            tointeger(null)
                          ) = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148695"
                        ),
                        characterLimit: 100
                      )
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_textField"(
                        label: "Expected MD Promotion Date per nomination",
                        labelPosition: "ABOVE",
                        value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                          value: index(ri!nomination, "mdPromotionDate", {}),
                          isBoolean: false
                        ),
                        readOnly: true
                      )
                    )
                  }
                ),
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_textField"(
                        label: "Expected Partner Promotion Date per latest available pipeline",
                        labelPosition: "ABOVE",
                        instructions: "Note - Consider additional vetting based on promotion date and role type",
                        value: index(
                          ri!nomination,
                          "partnerPromotionDateHR",
                          null
                        ),
                        saveInto: { ri!nomination.partnerPromotionDateHR },
                        required: or(
                          index(
                            ri!nomination,
                            "subPositionTypeId",
                            tointeger(null)
                          ) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454622",
                          index(
                            ri!nomination,
                            "subPositionTypeId",
                            tointeger(null)
                          ) = #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4454629"
                        ),
                        disabled: index(
                          ri!nomination,
                          "subPositionTypeId",
                          tointeger(null)
                        ) = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4148688",
                        characterLimit: 100,

                      )
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_textField"(
                        label: "Is this candidate a future partner promote?",
                        labelPosition: "ABOVE",
                        value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                          value: index(
                            ri!nomination,
                            "isFuturePartnerPromote",
                            toboolean({})
                          ),
                          isBoolean: true
                        ),
                        readOnly: true
                      ),
                      showWhen: if(
                        toboolean(local!isOldVersion) = true,
                        false,
                        true
                      )
                    )
                    },
                ),
                /* Sahana Ananth -- added applicable pathway and pathway comments fields as part of APAP-28578 on 10-Nov-25*/
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item:
                        #"SYSTEM_SYSRULES_dropdownField_v1"(
                        label: "Which pathway is most applicable to the candidate per HR?",
                        instructions: "Note: All traditional w/ EQCR rotationals are expected to be an MD and designated on the 'Public' pathway.",
                        choiceLabels: index(local!applicablePathwaysPerHR,"description",null),
                        choiceValues: index(local!applicablePathwaysPerHR,"description",null),
                        value: index(ri!nomination,"applicablePathwayHR",null),
                        saveInto: ri!nomination.applicablePathwayHR,
                        placeholder: "--Select a value--",
                        required: true()
                      ),
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_textField"(
                        label: "Which pathway is most applicable to the candidate per nomination",
                        labelPosition: "ABOVE",
                        value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                          value: index(ri!nomination,"applicablePathway",{}),
                          isBoolean: false
                        ),
                        readOnly: true
                      ))

                  },

                ),
                #"SYSTEM_SYSRULES_sideBySideLayout"(
                  items: {
                    #"SYSTEM_SYSRULES_sideBySideItem"(),
                    if(toboolean(local!isOldVersion)=true,
                    #"SYSTEM_SYSRULES_sideBySideItem"(
                      item: #"SYSTEM_SYSRULES_textField"(
                        label: "Expected Partner Promotion Date per nomination",
                        labelPosition: "ABOVE",
                        value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                          value: index(
                            ri!nomination,
                            "partnerPromotionDate",
                            {}
                          ),
                          isBoolean: false
                        ),
                        readOnly: true
                      ),
                      showWhen: if(toboolean(local!isOldVersion)=true,true,false)
                    ),
                    #"SYSTEM_SYSRULES_sideBySideItem"())
                  }
                ),
              },
              width: if(
                #"SYSTEM_SYSRULES_isPageWidth"({ "DESKTOP_WIDE" }),
                "WIDE_PLUS",
                if(
                  #"SYSTEM_SYSRULES_isPageWidth"({ "DESKTOP" }),
                  "WIDE",
                  "AUTO"
                )
              )
            )
          },
          showDividers: true
        ),
        #"SYSTEM_SYSRULES_paragraphField"(
          label: "HR/Other Comments",
          labelPosition: "ABOVE",
          value: index(ri!nomination, "hrComments", null),
          saveInto: { ri!nomination.hrComments },
          refreshAfter: "UNFOCUS",
          characterLimit: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3238137",
          height: "MEDIUM",
          required: or(
            index(
              ri!nomination,
              "isVettingRequired",
              toboolean({})
            ) = true,
            index(
              ri!nomination,
              "isAQR1or2",
              tostring(null)
            ) = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3197185"
          )
        )
      }
    )
  },
  showWhen: ri!showWhen,
  isCollapsible: true,
  divider: "ABOVE",
  dividerWeight: "THIN",
  /*dividerColor: "SECONDARY",*/
  marginBelow: "STANDARD"
)
)
